const $=selector=>document.querySelector(selector);const safe=value=>{const node=document.createElement('span');node.textContent=value||'—';return node.innerHTML};let users=[];
async function csrf(){const response=await fetch('/api/csrf-token',{credentials:'include',cache:'no-store'});if(!response.ok)throw new Error('تعذر بدء الجلسة الآمنة');return (await response.json()).token}
async function api(url,options={}){const method=String(options.method||'GET').toUpperCase(),headers={'Content-Type':'application/json',...(options.headers||{})};if(method!=='GET')headers['X-CSRF-Token']=await csrf();const response=await fetch(url,{...options,method,headers,credentials:'include',cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||'تعذر تحميل بيانات الإدارة');return data}
function setText(id,value){const node=document.getElementById(id);if(node)node.textContent=String(value??'—')}
function showError(error){const box=$('#adminError');if(!box)return;box.classList.remove('hidden');box.textContent=error.message||'تعذر تحميل البيانات. حاول مجددًا.'}
function render(list){const rows=$('#rows');if(!rows)return;rows.innerHTML=list.map(user=>`<tr data-id="${user.id}"><td><div class="person"><img src="${safe(user.avatar||'')}" alt=""><div><b>${safe(user.displayName||user.username)}</b><br><small>@${safe(user.username)}</small></div></div></td><td>${safe(user.email)}</td><td><select class="select plan"><option value="free" ${['free','trial'].includes(user.plan)?'selected':''}>Free</option><option value="starter" ${user.plan==='starter'?'selected':''}>Starter</option><option value="growth" ${user.plan==='growth'?'selected':''}>Growth</option><option value="business" ${['business','complete'].includes(user.plan)?'selected':''}>Business</option></select></td><td><select class="select status"><option value="active" ${user.status==='active'?'selected':''}>نشط</option><option value="suspended" ${user.status==='suspended'?'selected':''}>موقوف</option><option value="cancelled" ${user.status==='cancelled'?'selected':''}>ملغي</option></select></td><td>${new Date(user.createdAt).toLocaleDateString('ar-SA')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد حسابات</td></tr>'}
async function refresh(){const [{user},{stats},{users:list}]=await Promise.all([api('/api/me'),api('/api/admin/stats'),api('/api/admin/users')]);if(!user?.isAdmin){location.replace('/admin-login');return}setText('adminName',user.displayName||user.username||'الأدمن');const avatar=$('#avatar');if(avatar)avatar.src=user.avatar||'';setText('users',stats.users);setText('active',stats.active);setText('paid',Number(stats.starter||0)+Number(stats.growth||0)+Number(stats.business||0));setText('projects',stats.projects);const counts={Free:Number(stats.free||0),Starter:Number(stats.starter||0),Growth:Number(stats.growth||0),Business:Number(stats.business||0)},max=Math.max(1,Number(stats.users||0));for(const [name,value] of Object.entries(counts)){setText('count'+name,value);const bar=$('#bar'+name);if(bar)bar.style.width=`${Math.round(value/max*100)}%`}users=list;render(users);$('#adminError')?.classList.add('hidden')}
$('#rows')?.addEventListener('change',async event=>{const row=event.target.closest('tr[data-id]');if(!row)return;try{await api(`/api/admin/users/${row.dataset.id}`,{method:'PATCH',body:JSON.stringify({plan:row.querySelector('.plan').value,status:row.querySelector('.status').value})})}catch(error){showError(error);await refresh().catch(showError)}});$('#search')?.addEventListener('input',event=>{const query=event.target.value.toLowerCase();render(users.filter(user=>`${user.username} ${user.displayName||''} ${user.email||''}`.toLowerCase().includes(query)))});$('#refreshAdmin')?.addEventListener('click',()=>refresh().catch(showError));$('#logout')?.addEventListener('click',async()=>{await api('/api/logout',{method:'POST'});location.replace('/')});refresh().catch(showError);
